examples.code:
annotate service.SalesOrders with @(
  UI.LineItem: [
    { $Type: 'UI.DataField', Value: SalesOrderID, Label: 'Order' },
    { $Type: 'UI.DataField', Value: Status, Criticality: StatusCriticality },
    { $Type: 'UI.DataField', Value: GrossAmount },
    { $Type: 'UI.DataFieldForAction', Action: 'service.approve', Label: 'Approve' }
  ],
  UI.PresentationVariant: {
    SortOrder: [{ Property: CreatedAt, Descending: true }],
    Visualizations: ['@UI.LineItem']
  },
  Capabilities.SortRestrictions: { NonSortableProperties: [Note] }
);

annotate service.SalesOrders with {
  Status   @Common.Text: StatusText @UI.TextArrangement: #TextFirst;
  Customer @Common.SemanticObject: 'Customer';
};

onBeforeRebindTable: function (event) {
  const bindingParams = event.getParameter("bindingParams");
  bindingParams.filters.push(new Filter("CreatedBy", FilterOperator.EQ, this._currentUser));
  bindingParams.parameters.expand = "ToCustomer";
}

annotate service.SalesOrders with @(
  UI.SelectionFields: [ SalesOrderID, Customer, Status, CreatedAt ],
  Capabilities.FilterRestrictions: {
    RequiredProperties: [ CompanyCode ],
    NonFilterableProperties: [ Note ]
  }
);

annotate service.SalesOrders with {
  Status @Common.ValueListWithFixedValues
         @Common.ValueList: {
           CollectionPath: 'OrderStatuses',
           Parameters: [
             { $Type: 'Common.ValueListParameterInOut', LocalDataProperty: Status, ValueListProperty: 'Code' },
             { $Type: 'Common.ValueListParameterDisplayOnly', ValueListProperty: 'Text' }
           ]
         };
  InternalFlag @UI.Hidden;
};

annotate service.SalesOrders with {
  // 1 = read-only, 3 = editable, 7 = mandatory, computed by the service per order
  Discount     @Common.FieldControl: DiscountFieldControl;
  // never shown in the UI
  TechnicalKey @UI.Hidden;
  // hidden only for some orders
  CreditLimit  @UI.Hidden: IsCreditLimitHidden;
};

annotate service.SalesOrderItems with @(
  Common.SideEffects #QuantityChanged: {
    SourceProperties: [ Quantity, UnitPrice ],
    TargetProperties: [ NetAmount ],
    TargetEntities:   [ ToSalesOrder ]   // refresh the order header totals too
  }
);
